import math
from functools import reduce

def lcm(a, b):
    return abs(a*b) // math.gcd(a, b)

def list_lcm(numbers):
    if not numbers:
        return 1
    return reduce(lcm, numbers)

# Test n=4 for small k
n = 4
k_values = range(1, 10)
results = {}
for k in k_values:
    x_k = list_lcm(range(k, k + n))
    x_k_plus_1 = list_lcm(range(k + 1, k + 1 + n))
    results[k] = (x_k, x_k_plus_1, x_k_plus_1 > x_k)

print("k | x_k | x_{k+1} | x_{k+1} > x_k")
print("-" * 40)
for k, (x_k, x_k_plus_1, is_increasing) in results.items():
    print(f"{k} | {x_k} | {x_k_plus_1} | {is_increasing}")

